-- 0005: player-owned businesses and their staff. Mirrors later-schema.js (n: 5).
CREATE TABLE IF NOT EXISTS businesses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_id BIGINT NOT NULL, type TEXT NOT NULL, city_id TEXT NOT NULL, name TEXT NOT NULL, level BIGINT NOT NULL DEFAULT 1, paid BIGINT NOT NULL, bought_at BIGINT NOT NULL, settled_at BIGINT NOT NULL, accrued_gross BIGINT NOT NULL DEFAULT 0, accrued_costs BIGINT NOT NULL DEFAULT 0, day TEXT NOT NULL DEFAULT '', day_net BIGINT NOT NULL DEFAULT 0, earned_total BIGINT NOT NULL DEFAULT 0, UNIQUE (user_id, type));
CREATE INDEX IF NOT EXISTS ix_businesses_user ON businesses(user_id);
CREATE TABLE IF NOT EXISTS business_staff (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, business_id BIGINT NOT NULL, name TEXT NOT NULL, skill BIGINT NOT NULL, wage BIGINT NOT NULL, hired_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS ix_business_staff_biz ON business_staff(business_id);
